// 列表虚拟化窗口计算：scrollTop + rowHeight + viewportHeight -> 渲染区间
function windowRange(cfg) {
  const { scrollTop, rowHeight, viewportHeight, total, overscan } = cfg;
  const first = Math.floor(scrollTop / rowHeight);
  const visible = Math.ceil(viewportHeight / rowHeight);
  const start = Math.max(0, first - overscan);
  const end = Math.min(total, first + visible + overscan);   // 半开区间 [start, end)
  return { start, end, count: end - start, offsetY: start * rowHeight, visible };
}
function fmt(r) { return 'start=' + r.start + ' end=' + r.end + ' count=' + r.count + ' offsetY=' + r.offsetY; }

const cfg = { rowHeight: 40, viewportHeight: 400, total: 1000, overscan: 2 };
console.log('top=' + fmt(windowRange({ ...cfg, scrollTop: 0 })));
console.log('mid=' + fmt(windowRange({ ...cfg, scrollTop: 4000 })));
console.log('near_bottom=' + fmt(windowRange({ ...cfg, scrollTop: 39960 })));
console.log('clamped_top=' + fmt(windowRange({ ...cfg, scrollTop: -50 })));
console.log('visible_rows=' + windowRange({ ...cfg, scrollTop: 0 }).visible);
console.log('total=' + cfg.total);
console.log('window_never_exceeds_total=' + (windowRange({ ...cfg, scrollTop: 39960 }).end <= cfg.total));
